NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'PAULUS wanporon en Iesus Kristus amen pan kusoned en Kot Saunkamaur patail o Kristus Iesus, me kitail kaporoporeki,',
        2: 'Ong Timoteus nai seri melel ni poson mak o limpok, o popol sang ren Kot Sam o Kristus Iesus atail Kaun.',
        3: 'Duen ai poeki re om, en mimieta Episus ni ai pan kola Masetonien, pwe koe en kapung ong akai, ren der wia padak toror.',
        4: 'Pil der kamelele kasoi mal o padok en di toto, me kareda akamai ap sota sauasa koa dodok en Kot, me tapi sang poson.',
        5: 'Pwe aude pan kusoned limpok sang nan mongiong makelekel, o insen mau, o poson melel.',
        6: 'Sang mepukat akai muei sanger, rap wuki ong poupoulap.',
        7: 'Re men wiala saunpadak en kapung, ap so weweki, me re inda, o me re kin men padaki kaualap.',
        8: 'A kitail asa, kapung me mau, ma amen so kasapunge.',
        9: 'O se asa, me sota kapung en wiaui ong me pung amen, a ong me sapung kan, o katiwo kan, o me doo sang Kot akan, o me dipan akan, o me so saraui kan, o me san Kot akan, o me kin kaloke sam ar in ar, o me kamela aramas akan.',
        10: 'O me nenek kan, o me madong saut ong ol oko, o me kin pirap aramas akan, o me likam kan, o me kaula likam akan, o ma pil meakot mia, me so kon ong padak en kamour.',
        11: 'Duen rongamau en lingan en Kot iasanai me pang dong ia.',
        12: 'I ap danke Kristus Iesus atail Kaun, me kotin kamana ia da o kamelel ia ni a kotin kasapwil ia dang dodok.',
        13: 'Pwe mas o ngai lalaue amen, o kaloke saulang kan, o lolap amen, ari so i diaradar mak o, pwe i wiadar mepukat ap sasa o ni ai soposon.',
        14: 'A mak en atail Kaun me lapalap alar kaualap ni poson o limpok, me mi ren Kristus Iesus.',
        15: 'Melel lepen kasoi lep, o me mau ong kamelele: Kristus Iesus pwara dong sappa, pwen dorela me dipan akan; a ngai me sued sang karos.',
        16: 'Ari so, i diaradar mak o, pwe Iesus Kristus en kotin kasaleda a kanongama lapalap re i, pwe men kaalemongi ong me pan poson, pwen maur soutuk.',
        17: 'A Nanmarki potopot, me so kak mor pasang, o so sansal, i Kot eta. Wau o lingan en ko ong i potopoteta! Amen.',
        18: 'Kusoned wet i men pang ong uk, nai seri Timoteus, duen deideikop akan, me wiaui ong uk er, pwe ren sauasu uk, en wia pei mau eu,',
        19: 'Ni om dadaurata poson o kanakanai ong insen om mau, me akai pein kase sang irail, ap peila sang nin poson.',
        20: 'Amen irail Imenäus o amen Aleksander, me pangalang Satan, pwe ren lelapok ki kalokolok, ap solar lalaue.',
    },
    2: {
        1: 'Iet me i men panaui mas: Komail ngidingideki o kapakapki, o poekipoeki aramas akan karos, o wia danke.',
        2: 'Kapakapaki nanmarki o saumas akan karos, pwe sen meleilei o insememau, wiawia me kon ong Kot o melel.',
        3: 'Pwe i me mau o kon ong atail Saunkamaur Kot,',
        4: 'Me kotin men, aramas akan karos en dorela o lolekong kila melel.',
        5: 'Pwe Kot me ta men o wilia patail me ta men nan pung en Kot o aramas akan, iet Aramas Kristus Iesus.',
        6: 'Me kotin wiala en aramas karos ar men pwaipwai, kadede en met, en lolok sili ni ansau me kon ong.',
        7: 'I me i wia kila saunkair o wanporon amen, i kin lokaia melel o so likam, o saunpadak ong men liki kan ni poson o melel.',
        8: 'I me i men, ol akan en kapakap ni wasa karos, ni ar pokada pa ar saraui, so makar o so peikasal.',
        9: 'Pil dueta li akan, ren kapwadeki likau makelekel o lelapok, o tiak mau, a kaidin ni ingid pit en monga, de kold, de manaman akan, de likau lingan,',
        10: 'A me kon ong li akan, me men kasaleda ar masak Kot ni ar wiawia mau kan.',
        11: 'Li akan en nenenla, ap padapadakki ni tiak en impimpai.',
        12: 'I sota mueid ong li amen, en wiada padak, de kaunda ol, a en nenenla.',
        13: 'Pwe Adam me wiauier mas, a muri Ewa.',
        14: 'A kaidin Adam, me katiamaula, a li o me katiamaular, ap pupedi ni me sapung.',
        15: 'A a pan dorela ni a naitik ma a pan podidi ong poson, o limpok, o saraui, o tiak mau.',
    },
    3: {
        1: 'MELEL kasoi pot et: Ma amen rapaki koa en pisop, a kin inong iong wiawia mau eu.',
        2: 'A pisop o en pung, o warok en li ta men, o so kowei kodo, a lelapok, o tiak mau, o apwali men kairu, o koiok ong padak;',
        3: 'A der kamom soko, o so pamara, a en materok, o der inong iong akamai, o der pok ong moni.',
        4: 'Me kin kaunda mau pein toun im a, o me na seri kan kin peiki ong ni tiak pung.',
        5: 'A ma amen, me sokoiok ong kaunda pein toun im a, iaduen a pan kak kaunda momodisou en Kot?',
        6: 'Pil kaidin saulang kap amen, pwe a ende aklapalap, ap lodi ong kadeik en tewil.',
        7: 'O en pil kalok mau ren me mi liki, pwe a de lodi ong kanamenok o katikatiamau pan tewil.',
        8: 'Pil dueta saunkoa kan en lelapok, so lo riapot, so kamom soko, so noroke moni.',
        9: 'Me kin kolekol nan insen arail makelekel rir en poson.',
        10: 'Mepukat en kasosongla mas, irail ap pan papa, ma irail me pung.',
        11: 'Pil dueta en saunkoa ar warok kan, ren wia me kon ong, o so likinekine, o so kowei kodo, o melel ni meakaros.',
        12: 'Saunkoa kan en warok en li ta men o ren kaunda mau nair seri kan o toun im arail.',
        13: 'A me papa mau, kin kalok maui pein irail, o re pan pereperenki melel poson me mi ren Kristus Iesus.',
        14: 'Mepukat i inting wong uk, o i kaporoporeki, me i pan pwarala re om madang.',
        15: 'A ma i pwapwand, koe en asa duen me koe pan wia nan tanpas en Kot, iei momodisou en Kot ieias, o ur o pason en melel.',
        16: 'Meid lapalap rir en pai ren Kot: Kot sansaleda ni uduk, ap diarokada me pung amen ren Ngen, ap pwaralang tounlang kan, ap lolok ong men liki kan, ap kamelel lar ren toun sappa, ap peukadalang wasa lingan.',
    },
    4: {
        1: 'A NGEN me kotin kokop melel, ni imwin kaua akai pan pupe wei sang poson, ap id wuki ong ngen widing o padak en tewil akan,',
        2: 'Me kin sansale mau ki liki, ap likilikam o insen arail kakaluakalar ki kisin mata karakar.',
        3: 'Re kin inapwiedi kapapaud, o dene ren liki sang song en manga, me Kot kotin wiadang irail, me danke, o poson, o dedekila melel o.',
        4: 'Pwe audepa karos, en Kot me mau, o sota meakot me mal, ma aramas pan tungole ap danke.',
        5: 'Pwe a pan kasaraui kila masan Kot o kapakap.',
        6: 'Ma koe pan padaki ong ri atail akan, koe ap pan papa en Kristus Iesus mau amen, me kin keleki masan en poson o padak mau, me koe dadaureta mau lel met.',
        7: 'A koe en kang kasoi likam en li laud akai o kaianeki pein uk me kon ong Kot.',
        8: 'Pwe kaiane kin uk pali war, a sota non katepa, a meid mau paieki Kot ni meakaros, pwe iei kaporopor en maur et o pil maur kokodo.',
        9: 'Nan melel kasoi pot et o a war ong kitail en apwaliela.',
        10: 'Pwe iet me se kin dodok ong o kalokolokki, at kaporoporeki Kot ieias, me Saunkamaur en aramas akan karos, a mas ong irail me poson.',
        11: 'Mepukat koe en katitiki o kaukaweweki.',
        12: 'Sota amen me pan mamaleki om manakap, a wiala men kaalemongi ong saulang kan, ni om lokaia o wiawia kan, o limpok, o poson, o makelekel.',
        13: 'O nantiong wadok, o panaui, o padak lao i pan pwar wei.',
        14: 'Der kasamal la pai en mak o, me koe aleer ki deideikop o ni en saunkoa kan ar pwil pa ar po om.',
        15: 'Koe en podidi o sopisokki mepukat, pwe om lolekong en sansal ong karos.',
        16: 'Kalaka pein uk o padak o, tengedi ong song pukat, pwe ma koe pan wiada due, koe ap pan dorela pein uk o pil, me kin rong uk.',
    },
    5: {
        1: 'KOE der lokaia kelail ong ol laud amen, a panaui i due sam amen, a me pulepul due ri om akan,',
        2: 'Li laud due in akan, a me pulepul due ri om li akan ni makelekel melel.',
        3: 'Kakaki li odi kan, me li odi melel.',
        4: 'A ma li odi na seri kan mia, de wa en na seri ko, re pan padakki mas apwali pein ar penainai, o depuk ong ar papa o nono, pwe i me mau o kon ong Kot.',
        5: 'A iet li odi melel amen, me kelep, me kin kaporoporeki Kot, o podidi ong ngidingid o kapakap akan ni pong o ni ran.',
        6: 'A me kin kapwaiada a inong sued nan i melar ni a memaur.',
        7: 'Mepukat padapadaki, pwe ren sota karaunepa.',
        8: 'A ma amen sota kin apwali na kan, a mas toun im a kan, i me kasela poson, o a sued sang me soposon amen.',
        9: 'Li odi men pan kileledi, ma a sota pulepul sang saunpar woneisok o ma a warok en ol ta men.',
        10: 'O me kalok mau ki a wiawia mau, o me wiada seri, o me apwali men kairu, o me widen nä en saraui kan, o me kadek ong me kamekame kan, o me kapwaiada song en wiawia mau karos.',
        11: 'A der tuki ong li odi pulepul akan, pwe irail lao inong wei sang Kristus, re men pur ong papaud.',
        12: 'A irail pan pakadeikada, pwe re muei sanger tapin poson.',
        13: 'A re pil ponkake o papang sili im akan, a kaidin ponkaka ta, pwe re pil poupou sili, o pil usa sili en amen a wiawia, o ar lokelokaia me sota mau.',
        14: 'A i men, li odi pulepul en papaud, o naitik, o apwali im ar, o der kare ong me sued o, en lalaue.',
        15: 'Pwe akai me wuki wei, wuki ong Satan.',
        16: 'A ma li odi men mi ren ol me poson amen de ren li me poson amen, a en pein apapwali i o der katoutoui momodisou, pwen itar ong me li odi melel.',
        17: 'Saunkoa kan me kin dodok mau, pan waunla melel, ir me kin sauasa ni padak o kawewe.',
        18: 'Pwe kisin likau o masani: Koe der penadi au en kau ol, me tiakedi wan wit. O toun dodok me war ong pwain en dodok.',
        19: 'Karaun pan saunkoa men der kamelele, ma so saunkadede riamen de silimen mia.',
        20: 'Ir me wia dip, kapung ong mon karos, pwe me tei kan en masakala.',
        21: 'I kakaliki ong uk mon Kot Kristus Iesus o tounlang lipilipil akan, koe en wiada mepukat, o so lipilipil, o so pwen konekon ren aramas.',
        22: 'Der madang pokadang pon amen pa om, o pil der dipane kila dip en amen kai, a pein koe en makelekel.',
        23: 'Koe der nim pil, a wain kis me kon ong kaped om o pweki om somau pan pak toto.',
        24: 'Dip en akai aramas me sansal ap mau ong kadeikada ansau wet, a dip en me tei kan pan sansal eu ran.',
        25: 'Pil dueta en akai ar wiawia mau me sansal metet, a me tei kan sota kak rirala.',
    },
    6: {
        1: 'LADU kan karos en wauneki melel ar saumas akan, pwe mar en Kot o lamalam der lalauela.',
        2: 'A irail me ar saumas akan kin poson ren der mamale kin ir aki ar saulang, a mak eta ren peiki ong irail, pweki ar lelapok o kompokelar. Mepukat padapadakiki o panauiki.',
        3: 'A ma amen kin wia eu padak toror, o a sota pan dadaurata masan mau en atail Kaun Iesus Kristus o lamalam, me kon ong Kot,',
        4: 'Nan a aklapalap o sota weweki meakot, a somauki akamai o lokaia sued, me kin kareda peirin, kapei lokaia, lalaue, o karaune mal.',
        5: 'O song en akamai en aramas akan, me kin suedela ni lol arail, re liki sang melel, re kiki ong, me pai ren Kot pan kareda kapwa.',
        6: 'A pai ren Kot o lolapot, iei me pai kasampwalia.',
        7: 'Pwe sota, me kitail wa dong sappa a sansal, me kitail pil sota pan wawei sang meakot.',
        8: 'A ma kan atail kisin manga o at likau mia, kitail en insenemauki.',
        9: 'A irail, me inong iong kapwapwala, pan lodi ong songesong, o kotauepa kan, o inong sued, o kamatok, me kakirdilang aramas akan, wasan kamekam o sued.',
        10: 'Pwe limpok ong moni me tapin song sued karos, me akai inong iong, rap salongala sang poson o kare ong pein irail kamadak toto.',
        11: 'A koe aramas en Kot amen, tang wei sang mepukat, a inong iong me pung o pai ren Kot, poson, limpok, kanongama, opampap en Ngen.',
        12: 'Wiada pei mau en poson, aneki maur soutuk, me koe pil paeker ong o kadededa kadede mau o mon saunkadede toto.',
        13: 'I kakaliki ong uk mon Kot, me kotin kamaureda meakaros o mon Kristus Iesus, me kotin kadededa mon Pontius Pilatus kadede mau o.',
        14: 'Koe en kanikid kusoned, o so samin, o so sapung, lao en atail Kaun Iesus Kristus a kotin pwarado,',
        15: 'Me Kaun iasanai pan kasansaleda ni a ansau, iei Nanmarki en nanmarki kan o Kaun en kaun akan,',
        16: 'Pwe i eta ieias soutuk, me kotikot nan marain, me sota meamen kak ong, me sota aramas kilanger, o so kak kilang, i en waunla manaman soutuk! Amen.',
        17: 'Koe en kapung ong me kapwapwaki dipisou en sappa et, me re der aklapalap o pil der kaporoporeki kapwa somelel, a Kot, me kupurai ong kitail sapan meakan karos, pwe kitail en paie kida.',
        18: 'Irail en dadaureta ni arail wiawia mau kan, o ren rokekila dok mau kan, o nek pasang, o sapan men sauasa.',
        19: 'Wiawia ong pein irail pason mau eu o ki pena ong ansau kokodo pwe irail en konodi maur melel.',
        20: 'O Timoteus, pereki pai, me pangalang re om, ni om liki sang poupou mal kai o padak likam en me aklolekong.',
        21: 'Me akai lodi ong ap salongala sang poson. Mak o en me re om!',
    },
}
